module mux2 (input a, input b, input s, output y);
  assign y = (~s & a) | (s & b);
endmodule

`timescale 1ns/1ns
module tb_mux2;
  reg a, b, s;
  wire y;
  integer errors = 0;
  mux2 uut (.a(a), .b(b), .s(s), .y(y));
  task check(input va, input vb, input vs, input exp);
    begin
      a = va; b = vb; s = vs;
      #10;
      if (y !== exp) begin
        errors = errors + 1;
        $display("FAIL t=%0t a=%b b=%b s=%b y=%b expected %b", $time, a, b, s, y, exp);
      end else
        $display("ok   t=%0t a=%b b=%b s=%b y=%b", $time, a, b, s, y);
    end
  endtask
  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb_mux2);
    check(1, 0, 0, 1);
    check(1, 0, 1, 0);
    check(0, 1, 0, 0);
    check(0, 1, 1, 1);
    if (errors == 0) $display("PASS: 4 vectors");
    else $display("FAIL: %0d errors", errors);
    $finish;
  end
endmodule
